// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsConfigPath 是约定的阈值配置文件路径（相对模块根）。
const thresholdsConfigPath = "config/thresholds.json"

// configPath 覆盖阈值配置文件路径；为空时从当前工作目录向上自动定位。
// 测试用它把配置指向临时文件。
var configPath string

// resolveConfigPath 返回阈值配置文件路径：优先用 configPath，
// 否则从 cwd 向上找到最近的 config/thresholds.json，兼容从仓库根或包目录启动。
func resolveConfigPath() string {
	if configPath != "" {
		return configPath
	}
	dir, err := os.Getwd()
	if err != nil {
		return thresholdsConfigPath
	}
	for {
		candidate := filepath.Join(dir, thresholdsConfigPath)
		if _, err := os.Stat(candidate); err == nil {
			return candidate
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return thresholdsConfigPath
		}
		dir = parent
	}
}

// loadThresholds 读取并解析阈值配置。文件缺失或格式非法时返回 nil，
// 调用方据此回退到 DefaultLowStockThreshold。
func loadThresholds() map[string]int {
	data, err := os.ReadFile(resolveConfigPath())
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// thresholdFor 返回仓库阈值，未配置的仓库回退到默认值。
func thresholdFor(warehouse string, thresholds map[string]int) int {
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 每次调用都重新读取 config/thresholds.json，所以运维直接改文件就生效，
// 不需要重新构建或重启。未配置的仓库回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	return thresholdFor(warehouse, loadThresholds())
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	thresholds := loadThresholds()
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if quantity < thresholdFor(warehouse, thresholds) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}
```

