package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// withThresholdsConfig 把阈值配置指向一个临时文件，测试结束后还原自动定位。
func withThresholdsConfig(t *testing.T, contents string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if err := os.WriteFile(path, []byte(contents), 0o600); err != nil {
		t.Fatal(err)
	}
	configPath = path
	t.Cleanup(func() { configPath = "" })
	return path
}

func TestPerWarehouseThresholds(t *testing.T) {
	withThresholdsConfig(t, `{"shanghai": 3, "beijing": 10}`)

	if got := LowStockThreshold("shanghai"); got != 3 {
		t.Fatalf("LowStockThreshold(shanghai) = %d, 期望配置值 3", got)
	}
	if got := LowStockThreshold("beijing"); got != 10 {
		t.Fatalf("LowStockThreshold(beijing) = %d, 期望配置值 10", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置仓库 LowStockThreshold(chengdu) = %d, 期望默认值 %d",
			got, DefaultLowStockThreshold)
	}
}

func TestConfigEditTakesEffectWithoutRebuild(t *testing.T) {
	path := withThresholdsConfig(t, `{"shanghai": 3}`)
	if got := LowStockThreshold("shanghai"); got != 3 {
		t.Fatalf("改前 LowStockThreshold(shanghai) = %d, 期望 3", got)
	}

	// 直接改写文件，不重新构建也不重启，下一次调用就要读到新值。
	if err := os.WriteFile(path, []byte(`{"shanghai": 7}`), 0o600); err != nil {
		t.Fatal(err)
	}
	if got := LowStockThreshold("shanghai"); got != 7 {
		t.Fatalf("改配置后 LowStockThreshold(shanghai) = %d, 期望 7", got)
	}
}

func TestLowStockWarehousesUsesPerWarehouseThreshold(t *testing.T) {
	withThresholdsConfig(t, `{"shanghai": 3}`)

	// shanghai 阈值 3，库存 3 不低于阈值；beijing 未配置走默认 5，库存 3 低于阈值。
	got := LowStockWarehouses(map[string]int{"shanghai": 3, "beijing": 3})
	want := []string{"beijing"}
	if len(got) != len(want) {
		t.Fatalf("LowStockWarehouses = %v, 期望 %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("LowStockWarehouses = %v, 期望 %v", got, want)
		}
	}
}

func TestBadConfigFallsBackToDefault(t *testing.T) {
	t.Run("格式非法", func(t *testing.T) {
		withThresholdsConfig(t, `{"shanghai": `)
		if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
			t.Fatalf("非法配置 LowStockThreshold(shanghai) = %d, 期望默认值 %d",
				got, DefaultLowStockThreshold)
		}
	})

	t.Run("文件缺失", func(t *testing.T) {
		configPath = filepath.Join(t.TempDir(), "missing.json")
		t.Cleanup(func() { configPath = "" })
		if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
			t.Fatalf("缺文件 LowStockThreshold(shanghai) = %d, 期望默认值 %d",
				got, DefaultLowStockThreshold)
		}
	})
}

func TestResolveConfigPathFindsRepoConfig(t *testing.T) {
	configPath = ""
	path := resolveConfigPath()
	if _, err := os.Stat(path); err != nil {
		t.Fatalf("resolveConfigPath() = %q, 无法读取仓库配置：%v", path, err)
	}
}
